import React, { useEffect, useState } from 'react';

const Ahorro = ({ userId }) => {
    const [saveData, setSaveData] = useState({});
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    useEffect(() => {
        const fetchSaveData = async () => {
            try {
                const response = await fetch(`http://localhost:5000/api/forms/save/getSave/${userId}`);
                
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                
                const result = await response.json();
                setSaveData(result);
            } catch (error) {
                setError('Error fetching save data: ' + error.message);
            } finally {
                setLoading(false);
            }
        };

        if (userId) {
            fetchSaveData();
        }
    }, [userId]);

    if (loading) {
        return <div>Cargando datos...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="ahorro-content">
                <h3>Datos Ahorro</h3>
                <p>¿Tiene Meta Específica?: {saveData.hasSpecificGoal ? 'Sí' : 'No'}</p>
                <p>Monto Objetivo: ${saveData.targetAmount || 'No disponible'}</p>
                <p>Ahorros Semanales: ${saveData.weeklySavings || 'No disponible'}</p>
            </div>
        </div>
    );
};

export default Ahorro;
